/* Pure exploration logic; no network, no scoring of personal interpretations. */
(function(root){
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s??'').toLocaleLowerCase('de').replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
function filterFilms(list,{query='',kind='Alle',until=2025,videoOnly=false}={}){const q=normalize(query);return list.filter(f=>(kind==='Alle'||f.kind===kind)&&parseInt(f.year)<=Number(until)&&(!videoOnly||f.video||f.clip||f.fullVideo)&&(!q||normalize([f.title,f.year,f.director,f.country,f.mode,f.facts].join(' ')).includes(q)));}
function moveItem(order,id,delta){const next=[...order],i=next.indexOf(id),j=i+delta;if(i>=0&&j>=0&&j<next.length)[next[i],next[j]]=[next[j],next[i]];return next;}
function togglePair(pair,id){if(pair.includes(id))return pair.filter(x=>x!==id);return pair.length<2?[...pair,id]:[pair[1],id];}
function embedUrl(c){if(c.provider==='youtube'){const p=new URLSearchParams({rel:'0',playsinline:'1'});if(c.start!==undefined)p.set('start',c.start);if(c.end!==undefined)p.set('end',c.end);return 'https://www.youtube-nocookie.com/embed/'+c.id+'?'+p;}if(c.provider==='vimeo')return 'https://player.vimeo.com/video/'+c.id+'?dnt=1';return c.embed;}
const segments=[{id:'alp',name:'Auf der Alp',start:'03:00',color:'#a8b786'},{id:'begegnung',name:'Heidi & Peter',start:'15:00',color:'#c5a287'},{id:'buch',name:'Die Buchseite',start:'45:00',color:'#d2c7af'},{id:'stadt',name:'Über der Stadt',start:'53:20',color:'#849b9c'}];
function reflect(text){const n=normalize(text),words=n.match(/[a-z0-9]+/g)||[];if(words.length<5)return {title:'Ein Anfang. Was genau fällt dir auf?',items:['Halte einen sichtbaren Moment, einen Ton oder einen Zeitcode fest. Auch eine offene Frage zählt.']};const evidence=/\d{1,2}:\d{2}|sicht|seh|bild|blick|einstellung|farbe|licht|ton|musik|stimm|schnitt|hand|fenster|buch|zieg|szen|gesicht|kamera|hoer/.test(n);const relation=/weil|dadurch|deshalb|wirkt|wirkung|scheint|als ob|erzeug|vermut|laesst|macht|sodass|damit|durch|fuehl|erinnert/.test(n);const alternative=/vielleicht|andererseits|hingegen|koennte|auch anders|nicht sicher|moeglich|offen|frage|aber|obwohl/.test(n);return {title:'Deine Spur lässt sich weiterverfolgen.',items:[evidence?'Du nennst etwas Konkretes im Material. Prüfe, ob eine andere Person die Stelle wiederfinden kann.':'Ergänze eine konkrete Stelle im Bild oder Film: Was ist dort zu sehen oder zu hören?',relation?'Du verknüpfst Beobachtung und Wirkung. Was im Material trägt diese Verbindung?':'Welche Wirkung hat deine Beobachtung auf dich? Eine Verbindung wie «dadurch» oder «für mich» kann helfen.',alternative?'Du lässt Raum für eine andere Lesart. Welche Beobachtung würde zwischen beiden Deutungen entscheiden?':'Versuche eine zweite mögliche Deutung derselben Stelle. Was würde sich dadurch ändern?'],note:'Diese lokale Rückmeldung erkennt sprachliche Hinweise. Sie bewertet deine Deutung nicht; auch anders formulierte Gedanken können tragen.'};}
root.HeidiExplorer={esc,normalize,filterFilms,moveItem,togglePair,embedUrl,segments,reflect};
})(typeof window!=='undefined'?window:globalThis);
